    /**
     * Base path for the admin REST API for one particular realm.
     *
     * @param name realm name (not id!)
     */
    @Path("{realm}")
    public RealmAdminResource getRealmAdmin(@PathParam("realm") @Parameter(description = "realm name (not id!)") final String name) {
